import os
from flask import Flask, jsonify, render_template, request

from core.file_manager import FileManager
from core.patch_engine import PatchEngine
from core.prompt_builder import PromptBuilder

app = Flask(__name__)

file_manager = FileManager(os.environ.get("PROJECT_DIR"))
prompt_builder = PromptBuilder(file_manager)
patch_engine = PatchEngine(file_manager)


@app.get("/")
def index():
    return render_template("index.html", project_root=str(file_manager.root))


@app.get("/api/files")
def api_files():
    return jsonify({"files": file_manager.scan_files()})


@app.get("/api/browse")
def api_browse():
    path = request.args.get("path", "")
    return jsonify(file_manager.browse_dirs(path))


@app.post("/api/project")
def api_project():
    raw_path = (request.json or {}).get("path", "")
    try:
        new_root = file_manager.set_root(raw_path)
        return jsonify({"ok": True, "root": str(new_root)})
    except ValueError as e:
        return jsonify({"error": str(e)}), 400


@app.post("/api/smart_select")
def api_smart_select():
    task = (request.json or {}).get("task", "")
    return jsonify({"selected": file_manager.smart_select(task)})


@app.post("/api/build_prompt")
def api_build_prompt():
    data = request.json or {}
    result = prompt_builder.build(
        task=data.get("task", ""),
        file_specs=data.get("files", []),
        include_tree=bool(data.get("include_tree", True)),
        chunk_size=max(10000, int(data.get("chunk_size", 120000))),
        goal_step=int(data.get("goal_step", 1)),
        answers=data.get("answers", []),
        applied_log=data.get("applied_log", []),
    )
    return jsonify(result)


@app.post("/api/apply")
def api_apply():
    data = request.json or {}
    parsed = patch_engine.parse_response(
        response_text=data.get("text", ""),
        fallback_path=data.get("fallback_path", ""),
    )
    ops = parsed["ops"]
    results = patch_engine.execute(ops, apply_changes=bool(data.get("apply", False))) if ops else []

    if not ops and not parsed["need_files"] and not parsed["questions"]:
        results = [{
            "path": "-",
            "status": "error",
            "message": "No <<<EDIT>>>, <<<WRITE>>>, <<<NEED_FILES>>>, or <<<ASK>>> blocks found.",
        }]

    return jsonify({
        "results": results,
        "need_files": parsed["need_files"],
        "questions": parsed["questions"],
        "status_flag": parsed["status_flag"],
    })


@app.post("/api/undo")
def api_undo():
    count = file_manager.undo_last()
    if count == 0:
        return jsonify({"error": "Nothing to undo."}), 400
    return jsonify({"message": f"Reverted {count} file(s)."})


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000, debug=False)

import ast
import difflib
import json
import re
from core.file_manager import BackupEntry, FileManager


class PatchEngine:
    """Parses edits, file requests, interactive questions, and goal status from AI responses."""

    EDIT_RE = re.compile(
        r'<<<EDIT\s+path=["\']([^"\']+)["\']\s*>>>\s*\r?\n<<<OLD>>>\r?\n(.*?)\r?\n<<<NEW>>>\r?\n(.*?)\r?\n<<<END>>>',
        re.DOTALL,
    )
    WRITE_RE = re.compile(
        r'<<<WRITE\s+path=["\']([^"\']+)["\']\s*>>>\s*\r?\n(.*?)\r?\n<<<END>>>',
        re.DOTALL,
    )
    NEED_RE = re.compile(r"<<<NEED_FILES>>>\r?\n(.*?)\r?\n<<<END>>>", re.DOTALL)
    ASK_RE = re.compile(r"<<<ASK>>>\r?\n(.*?)\r?\n<<<END>>>", re.DOTALL)
    STATUS_RE = re.compile(r"<<<STATUS:\s*(NEED_MORE|APPLIED_NEXT|DONE)\s*>>>")

    def __init__(self, file_manager: FileManager) -> None:
        self._fm = file_manager

    @staticmethod
    def _strip_wrappers(text: str) -> str:
        t = text.strip()
        if t.startswith("<<>>") and t.endswith("<<>>"):
            t = t[4:-4].strip()
        m = re.match(r"^```[a-zA-Z0-9_-]*\r?\n(.*)\r?\n```$", t, re.DOTALL)
        return m.group(1) if m else t

    def parse_response(self, response_text: str, fallback_path: str = "") -> dict:
        ops: list[dict] = []
        for m in self.EDIT_RE.finditer(response_text):
            ops.append({"type": "edit", "path": m.group(1), "old": m.group(2), "new": m.group(3)})
        for m in self.WRITE_RE.finditer(response_text):
            ops.append({"type": "write", "path": m.group(1), "content": m.group(2)})

        need_files: list[dict] = []
        for m in self.NEED_RE.finditer(response_text):
            for raw_line in m.group(1).splitlines():
                line = raw_line.strip()
                if not line:
                    continue
                if ":" in line:
                    path_part, spec_part = line.rsplit(":", 1)
                    spec_part = spec_part.strip().lower()
                    if "-" in spec_part:
                        s, e = spec_part.split("-", 1)
                        need_files.append({
                            "path": path_part.strip(),
                            "mode": "range",
                            "start": int(s) if s.isdigit() else "",
                            "end": int(e) if e.isdigit() else "",
                        })
                    elif spec_part in ("full", "outline"):
                        need_files.append({"path": path_part.strip(), "mode": spec_part})
                    else:
                        need_files.append({"path": line, "mode": "full"})
                else:
                    need_files.append({"path": line, "mode": "full"})

        questions: list[dict] = []
        for m in self.ASK_RE.finditer(response_text):
            lines = [l.strip() for l in m.group(1).splitlines() if l.strip()]
            if not lines:
                continue
            q_text = lines[0]
            opts = [l[1:].strip() for l in lines[1:] if l.startswith("-")]
            questions.append({"question": q_text, "options": opts})

        status_match = self.STATUS_RE.search(response_text)
        status_flag = status_match.group(1) if status_match else ""

        if not ops and not need_files and not questions and fallback_path.strip() and response_text.strip():
            ops.append({
                "type": "write",
                "path": fallback_path.strip(),
                "content": self._strip_wrappers(response_text),
            })

        return {
            "ops": ops,
            "need_files": need_files,
            "questions": questions,
            "status_flag": status_flag,
        }

    @staticmethod
    def _validate_syntax(rel_path: str, content: str) -> str | None:
        lower = rel_path.lower()
        if lower.endswith(".py"):
            try:
                ast.parse(content, filename=rel_path)
            except SyntaxError as e:
                return f"Python SyntaxError on line {e.lineno}: {e.msg}"
        elif lower.endswith(".json"):
            try:
                json.loads(content)
            except json.JSONDecodeError as e:
                return f"JSON SyntaxError on line {e.lineno}, col {e.colno}: {e.msg}"
        return None

    @staticmethod
    def _preserve_newlines(new_text: str, use_crlf: bool) -> str:
        normalized = new_text.replace("\r\n", "\n")
        return normalized.replace("\n", "\r\n") if use_crlf else normalized

    @staticmethod
    def _build_diff_lines(old_text: str, new_text: str, rel_path: str) -> list[dict]:
        raw_diff = difflib.unified_diff(
            old_text.splitlines(),
            new_text.splitlines(),
            fromfile=f"a/{rel_path}",
            tofile=f"b/{rel_path}",
            lineterm="",
        )
        structured = []
        for line in raw_diff:
            if line.startswith("+++") or line.startswith("---"):
                kind = "meta"
            elif line.startswith("@@"):
                kind = "hunk"
            elif line.startswith("+"):
                kind = "add"
            elif line.startswith("-"):
                kind = "del"
            else:
                kind = "ctx"
            structured.append({"kind": kind, "text": line})
        return structured

    def execute(self, ops: list[dict], apply_changes: bool = False) -> list[dict]:
        results: list[dict] = []
        backups: list[BackupEntry] = []

        for op in ops:
            rel = op["path"]
            try:
                if op["type"] == "edit":
                    old_full = self._fm.read_raw(rel)
                    use_crlf = "\r\n" in old_full
                    norm_full = old_full.replace("\r\n", "\n")
                    norm_old = op["old"].replace("\r\n", "\n")
                    norm_new = op["new"].replace("\r\n", "\n")

                    count = norm_full.count(norm_old)
                    if count == 0:
                        results.append({"path": rel, "status": "error", "message": "Sensitive OLD block not found (check exact case/indentation)."})
                        continue
                    if count > 1:
                        results.append({"path": rel, "status": "error", "message": f"Sensitive match found {count} occurrences; include more context lines."})
                        continue

                    new_full = self._preserve_newlines(norm_full.replace(norm_old, norm_new, 1), use_crlf)

                elif op["type"] == "write":
                    try:
                        old_full = self._fm.read_raw(rel)
                        use_crlf = "\r\n" in old_full
                    except FileNotFoundError:
                        old_full = ""
                        use_crlf = False
                    new_full = self._preserve_newlines(op["content"], use_crlf)
                else:
                    continue

                syntax_err = self._validate_syntax(rel, new_full)
                if syntax_err:
                    results.append({"path": rel, "status": "error", "message": syntax_err})
                    continue

                diff_lines = self._build_diff_lines(old_full, new_full, rel)
                if apply_changes:
                    self._fm.write_with_backup(rel, new_full, backups)
                results.append({
                    "path": rel,
                    "status": "applied" if apply_changes else "ready",
                    "diff_lines": diff_lines,
                })
            except Exception as e:
                results.append({"path": rel, "status": "error", "message": str(e)})

        if apply_changes:
            self._fm.commit_undo_batch(backups)
        return results

