.badge.goal.active { background: #78350f; color: #fbbf24; }
.project-bar { display: flex; gap: 8px; flex: 1; max-width: 620px; }
.layout { display: grid; grid-template-columns: 340px 1fr; gap: 16px; padding: 16px 20px; max-width: 1440px; margin: 0 auto; }
.card { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 14px; display: flex; flex-direction: column; gap: 10px; }
.card-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.card-head h3 { margin: 0; font-size: 14px; font-weight: 600; }
.sidebar { height: calc(100vh - 92px); }
.workspace { display: flex; flex-direction: column; gap: 16px; }
input, textarea, select { background: var(--panel); color: var(--text); border: 1px solid #374151; border-radius: 6px; padding: 8px 10px; font-size: 13px; width: 100%; }
textarea { min-height: 95px; resize: vertical; font-family: inherit; }
textarea.mono { font-family: ui-monospace, Consolas, monospace; font-size: 12px; }
textarea.small { min-height: 80px; }
.num-input { width: 95px; display: inline-block; margin-left: 4px; }
.row { display: flex; gap: 8px; align-items: center; }
.wrap { flex-wrap: wrap; }
.btn { border: none; border-radius: 6px; padding: 8px 12px; font-size: 13px; font-weight: 600; cursor: pointer; color: #fff; white-space: nowrap; }
.btn.primary { background: var(--primary); }
.btn.success { background: var(--success); }
.btn.warn { background: var(--warn); }
.btn.ghost { background: #374151; }
.btn:hover { filter: brightness(1.1); }
.file-list { flex: 1; overflow-y: auto; border: 1px solid var(--border); border-radius: 6px; padding: 6px; background: var(--panel); }
.fitem { display: flex; align-items: center; gap: 8px; padding: 4px 6px; border-radius: 4px; font-size: 12px; font-family: ui-monospace, monospace; cursor: pointer; }
.fitem:hover { background: #1e293b; }
.fitem input { width: auto; }
.fmeta { margin-left: auto; color: var(--muted); font-size: 11px; }
.token-meter { display: flex; justify-content: space-between; font-size: 12px; padding-top: 6px; border-top: 1px solid var(--border); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { display: flex; align-items: center; gap: 6px; background: #1e293b; border: 1px solid #334155; border-radius: 6px; padding: 4px 8px; font-size: 12px; }
.chip select { width: auto; padding: 2px 6px; font-size: 11px; }
.chip input.rng { width: 64px; padding: 2px 6px; font-size: 11px; }
.qa-container { display: flex; flex-direction: column; gap: 10px; }
.qa-card { background: #0f172a; border: 1px solid #3b82f6; border-radius: 8px; padding: 10px 12px; display: flex; flex-direction: column; gap: 6px; }
.qa-title { font-weight: 600; font-size: 13px; color: #93c5fd; }
.qa-opt { display: flex; align-items: center; gap: 8px; font-size: 13px; cursor: pointer; }
.qa-opt input { width: auto; }
.diff-container { display: flex; flex-direction: column; gap: 10px; max-height: 360px; overflow-y: auto; }
.diff-file { border: 1px solid var(--border); border-radius: 6px; overflow: hidden; background: #020617; }
.diff-header { display: flex; justify-content: space-between; padding: 6px 10px; background: #1e293b; font-family: ui-monospace, monospace; font-size: 12px; font-weight: 600; }
.diff-header.ready, .diff-header.applied { color: var(--add-fg); }
.diff-header.error { color: var(--del-fg); }
.diff-body { font-family: ui-monospace, Consolas, monospace; font-size: 12px; line-height: 1.45; overflow-x: auto; }
.dline { padding: 1px 10px; white-space: pre; }
.dline.add { background: var(--add-bg); color: var(--add-fg); }
.dline.del { background: var(--del-bg); color: var(--del-fg); }
.dline.hunk { color: var(--hunk-fg); background: rgba(56, 189, 248, 0.08); }
.dline.meta { color: var(--muted); }
.muted { color: var(--muted); font-size: 12px; }
.chk { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--muted); cursor: pointer; }
.chk input { width: auto; }
.modal { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.65); display: flex; align-items: center; justify-content: center; z-index: 50; }
.modal.hidden { display: none; }
.modal-card { background: var(--card); border: 1px solid #334155; border-radius: 10px; padding: 16px; width: min(560px, 92vw); display: flex; flex-direction: column; gap: 10px; }
.toast { position: fixed; bottom: 20px; right: 20px; background: #1e293b; border: 1px solid #475569; padding: 10px 16px; border-radius: 8px; font-size: 13px; opacity: 0; transition: opacity 0.2s; pointer-events: none; z-index: 60; }
.toast.show { opacity: 1; }
@media (max-width: 900px) { .layout { grid-template-columns: 1fr; } .sidebar { height: 320px; } }

const App = {
  files: [],
  selected: new Map(), // path -> { path, mode, start, end, tokens }
  browseParent: "",
  goalStep: 1,
  appliedLog: [],
  pendingQuestions: [], // [{ question, options }]

  toast(msg) {
    const el = document.getElementById("toast");
    el.textContent = msg;
    el.classList.add("show");
    setTimeout(() => el.classList.remove("show"), 2200);
  },

  setGoalBadge(stateText, cls = "") {
    const b = document.getElementById("goalBadge");
    b.textContent = `Goal: Step ${this.goalStep} (${stateText})`;
    b.className = `badge goal ${cls}`;
  },

  resetGoal() {
    this.goalStep = 1;
    this.appliedLog = [];
    this.pendingQuestions = [];
    document.getElementById("questionsOut").innerHTML = "";
    document.getElementById("diffOut").innerHTML = "";
    document.getElementById("aiResponse").value = "";
    this.setGoalBadge("IDLE");
    this.toast("Goal reset");
  },

  async loadFiles() {
    const res = await fetch("/api/files");
    const data = await res.json();
    this.files = data.files || [];
    this.renderFiles();
  },

  async setProject(customPath = null) {
    const path = customPath !== null ? customPath : document.getElementById("projPath").value;
    const res = await fetch("/api/project", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error);
    document.getElementById("projPath").value = data.root;
    this.selected.clear();
    this.renderChips();
    this.resetGoal();
    await this.loadFiles();
    this.toast("Project loaded");
  },

  async smartSelect() {
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Enter a task first so Smart Select can match files.");
    const res = await fetch("/api/smart_select", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ task }),
    });
    const data = await res.json();
    this.selected.clear();
    (data.selected || []).forEach((s) => {
      this.selected.set(s.path, { path: s.path, mode: s.mode, start: "", end: "", tokens: s.tokens || 500 });
    });
    this.renderFiles();
    this.renderChips();
    this.toast(`Smart Select picked ${this.selected.size} file(s)`);
  },

  async openBrowser() {
    document.getElementById("browserModal").classList.remove("hidden");
    await this.browseTo(document.getElementById("projPath").value);
  },

  closeBrowser() {
    document.getElementById("browserModal").classList.add("hidden");
  },

  async browseTo(path) {
    const res = await fetch(`/api/browse?path=${encodeURIComponent(path || "")}`);
    const data = await res.json();
    document.getElementById("browsePath").value = data.current;
    this.browseParent = data.parent || "";
    document.getElementById("upBtn").disabled = !this.browseParent;

    const drives = document.getElementById("driveBar");
    drives.innerHTML = "";
    (data.drives || []).forEach((d) => {
      const b = document.createElement("button");
      b.className = "btn ghost";
      b.textContent = d;
      b.onclick = () => this.browseTo(d);
      drives.appendChild(b);
    });

    const list = document.getElementById("dirList");
    list.innerHTML = "";
    (data.dirs || []).forEach((d) => {
      const row = document.createElement("div");
      row.className = "fitem";
      row.textContent = "📁 " + d.name;
      row.onclick = () => this.browseTo(d.path);
      list.appendChild(row);
    });
  },

  browseUp() {
    if (this.browseParent) this.browseTo(this.browseParent);
  },

  async selectBrowsed() {
    const chosen = document.getElementById("browsePath").value;
    this.closeBrowser();
    await this.setProject(chosen);
  },

  renderFiles() {
    const q = document.getElementById("filter").value.toLowerCase();
    const list = document.getElementById("fileList");
    list.innerHTML = "";

    this.files.forEach((f) => {
      if (q && !f.path.toLowerCase().includes(q)) return;
      const row = document.createElement("label");
      row.className = "fitem";
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = this.selected.has(f.path);
      cb.onchange = () => {
        if (cb.checked) {
          const defaultMode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode: defaultMode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
        this.renderChips();
        this.updateStats();
      };
      const name = document.createElement("span");
      name.textContent = f.path;
      const meta = document.createElement("span");
      meta.className = "fmeta";
      meta.textContent = `~${f.est_tokens}t`;
      row.append(cb, name, meta);
      list.appendChild(row);
    });
    this.updateStats();
  },

  renderChips() {
    const box = document.getElementById("selectedChips");
    box.innerHTML = "";
    this.selected.forEach((spec, path) => {
      const chip = document.createElement("div");
      chip.className = "chip";
      const lbl = document.createElement("span");
      lbl.textContent = path;

      const sel = document.createElement("select");
      ["full", "outline", "range"].forEach((m) => {
        const opt = document.createElement("option");
        opt.value = m;
        opt.textContent = m === "outline" ? "outline (save tokens)" : m;
        if (spec.mode === m) opt.selected = true;
        sel.appendChild(opt);
      });
      sel.onchange = () => {
        spec.mode = sel.value;
        this.renderChips();
        this.updateStats();
      };
      chip.append(lbl, sel);

      if (spec.mode === "range") {
        const sIn = document.createElement("input");
        sIn.className = "rng";
        sIn.placeholder = "start";
        sIn.value = spec.start;
        sIn.oninput = () => (spec.start = parseInt(sIn.value) || "");
        const eIn = document.createElement("input");
        eIn.className = "rng";
        eIn.placeholder = "end";
        eIn.value = spec.end;
        eIn.oninput = () => (spec.end = parseInt(eIn.value) || "");
        chip.append(sIn, eIn);
      }
      box.appendChild(chip);
    });
  },

  updateStats() {
    document.getElementById("fileStats").textContent = `${this.selected.size} / ${this.files.length} files`;
    let total = 0;
    this.selected.forEach((s) => {
      total += s.mode === "outline" ? Math.round(s.tokens * 0.2) : s.tokens;
    });
    document.getElementById("selectedTokens").textContent = `~${total.toLocaleString()} tokens`;
  },

  toggleAll(on) {
    const q = document.getElementById("filter").value.toLowerCase();
    this.files.forEach((f) => {
      if (!q || f.path.toLowerCase().includes(q)) {
        if (on) {
          const mode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
      }
    });
    this.renderFiles();
    this.renderChips();
  },

  collectAnswers() {
    const answers = [];
    this.pendingQuestions.forEach((q, idx) => {
      const checked = document.querySelector(`input[name="qa_${idx}"]:checked`);
      const custom = document.getElementById(`qa_custom_${idx}`).value.trim();
      const ans = custom || (checked ? checked.value : "");
      if (ans) answers.push({ question: q.question, answer: ans });
    });
    return answers;
  },

  async buildPrompt(isAutoNext = false) {
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Describe your goal first.");

    if (
      !isAutoNext &&
      this.goalStep === 1 &&
      this.selected.size === 0 &&
      document.getElementById("autoSelectSmart").checked
    ) {
      await this.smartSelect();
    }

    const include_tree = document.getElementById("includeTree").checked;
    const chunk_size = parseInt(document.getElementById("chunkSize").value) || 120000;
    const files = Array.from(this.selected.values());
    const answers = this.collectAnswers();

    const res = await fetch("/api/build_prompt", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        task,
        files,
        include_tree,
        chunk_size,
        goal_step: this.goalStep,
        answers,
        applied_log: this.appliedLog,
      }),
    });
    const data = await res.json();
    document.getElementById("generatedPrompt").value = data.full_prompt;
    document.getElementById("promptMeta").textContent =
      `${data.chars.toLocaleString()} chars (~${data.est_tokens.toLocaleString()} tokens)`;

    const btns = document.getElementById("copyButtons");
    btns.innerHTML = "";
    data.parts.forEach((part, idx) => {
      const b = document.createElement("button");
      b.className = "btn success";
      const label = data.parts.length === 1 ? "Copy Prompt" : `Copy Part ${idx + 1}/${data.parts.length}`;
      b.textContent = label;
      b.onclick = async () => {
        await navigator.clipboard.writeText(part);
        this.toast(`${label} copied!`);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
      };
      btns.appendChild(b);
    });

    if (data.parts && data.parts.length > 0) {
      const firstLabel = data.parts.length === 1 ? "Prompt" : `Part 1/${data.parts.length}`;
      try {
        await navigator.clipboard.writeText(data.parts[0]);
        this.toast(`${firstLabel} copied to clipboard!`);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
      } catch (e) {
        this.toast("Prompt generated (click Copy to copy)");
      }
    }

    this.setGoalBadge("IN PROGRESS", "active");
  },

  renderQuestions(questions) {
    this.pendingQuestions = questions || [];
    const box = document.getElementById("questionsOut");
    box.innerHTML = "";
    if (!this.pendingQuestions.length) return;

    this.pendingQuestions.forEach((q, idx) => {
      const card = document.createElement("div");
      card.className = "qa-card";
      const title = document.createElement("div");
      title.className = "qa-title";
      title.textContent = q.question;
      card.appendChild(title);

      (q.options || []).forEach((opt) => {
        const lbl = document.createElement("label");
        lbl.className = "qa-opt";
        const r = document.createElement("input");
        r.type = "radio";
        r.name = `qa_${idx}`;
        r.value = opt;
        r.onchange = () => {
          if (this.pendingQuestions.length === 1) {
            this.submitAnswersAndAdvance();
          }
        };
        lbl.append(r, document.createTextNode(opt));
        card.appendChild(lbl);
      });

      const custom = document.createElement("input");
      custom.id = `qa_custom_${idx}`;
      custom.placeholder = "Or type a custom answer and press Enter...";
      custom.onkeydown = (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          this.submitAnswersAndAdvance();
        }
      };
      card.appendChild(custom);
      box.appendChild(card);
    });

    const submitRow = document.createElement("div");
    submitRow.className = "row";
    const btn = document.createElement("button");
    btn.className = "btn primary";
    btn.textContent = "Send Answers & Copy Next Prompt →";
    btn.onclick = () => this.submitAnswersAndAdvance();
    submitRow.appendChild(btn);
    box.appendChild(submitRow);
  },

  async submitAnswersAndAdvance() {
    this.goalStep += 1;
    await this.buildPrompt(true);
    document.getElementById("aiResponse").value = "";
    this.renderQuestions([]);
    this.toast(`Step ${this.goalStep} prompt with answers copied!`);
  },

  async runOps(apply) {
    const text = document.getElementById("aiResponse").value;
    let fallback_path = document.getElementById("fallbackFile").value.trim();
    if (!fallback_path && this.selected.size === 1) {
      fallback_path = Array.from(this.selected.keys())[0];
    }

    const res = await fetch("/api/apply", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, apply, fallback_path }),
    });
    const data = await res.json();

    const hasQuestions = (data.questions || []).length > 0;
    const hasNeedFiles = (data.need_files || []).length > 0;

    // Handle AI interactive questions
    this.renderQuestions(data.questions || []);

    // Render Red/Green diffs
    const out = document.getElementById("diffOut");
    out.innerHTML = "";
    const results = data.results || [];
    document.getElementById("applyMeta").textContent =
      `${results.length} edit(s) · ${(data.need_files || []).length} file req(s) · ${(data.questions || []).length} question(s)`;

    let appliedCount = 0;
    let errorCount = 0;
    results.forEach((r) => {
      const card = document.createElement("div");
      card.className = "diff-file";
      const hdr = document.createElement("div");
      hdr.className = `diff-header ${r.status}`;
      hdr.textContent = `[${r.status.toUpperCase()}] ${r.path}`;
      card.appendChild(hdr);

      const body = document.createElement("div");
      body.className = "diff-body";
      if (r.message) {
        const line = document.createElement("div");
        line.className = "dline del";
        line.textContent = r.message;
        body.appendChild(line);
      } else if (r.diff_lines && r.diff_lines.length) {
        r.diff_lines.forEach((dl) => {
          const line = document.createElement("div");
          line.className = `dline ${dl.kind}`;
          line.textContent = dl.text;
          body.appendChild(line);
        });
      } else {
        const line = document.createElement("div");
        line.className = "dline meta";
        line.textContent = "(no text changes)";
        body.appendChild(line);
      }
      card.appendChild(body);
      out.appendChild(card);

      if (apply && r.status === "applied") {
        appliedCount += 1;
        this.appliedLog.push(`Step ${this.goalStep}: updated ${r.path}`);
      } else if (r.status === "error") {
        errorCount += 1;
      }
    });

    if (apply && appliedCount > 0) {
      await this.loadFiles();
    }

    // Handle AI-requested files automatically
    if (hasNeedFiles) {
      data.need_files.forEach((nf) => {
        const match = this.files.find((f) => f.path === nf.path);
        this.selected.set(nf.path, {
          path: nf.path,
          mode: nf.mode || "full",
          start: nf.start || "",
          end: nf.end || "",
          tokens: match ? match.est_tokens : 500,
        });
      });
      this.renderFiles();
      this.renderChips();

      if (!hasQuestions) {
        this.goalStep += 1;
        await this.buildPrompt(true);
        document.getElementById("aiResponse").value = "";
        this.setGoalBadge("WAITING NEXT", "active");
        this.toast(`Step ${this.goalStep}: copied ${data.need_files.length} requested file(s)!`);
        return;
      }
    }

    // Automatically advance to next step when AI indicates APPLIED_NEXT
    if (apply && data.status_flag === "APPLIED_NEXT" && !hasQuestions && errorCount === 0) {
      this.goalStep += 1;
      await this.buildPrompt(true);
      document.getElementById("aiResponse").value = "";
      this.setGoalBadge("WAITING NEXT", "active");
      this.toast(`Applied ${appliedCount} file(s) & copied Step ${this.goalStep} prompt!`);
      return;
    }

    if (data.status_flag === "DONE") {
      this.setGoalBadge("DONE", "done");
      if (apply && appliedCount > 0) this.toast(`Done! Applied ${appliedCount} file(s).`);
    } else if (hasQuestions || data.status_flag === "NEED_MORE" || data.status_flag === "APPLIED_NEXT") {
      this.setGoalBadge("WAITING INPUT", "active");
      if (hasQuestions) this.toast("Answer the question(s) below to continue.");
    } else if (apply && appliedCount > 0) {
      this.toast(`Applied ${appliedCount} file(s)!`);
    }
  },

  async nextGoalStep() {
    this.goalStep += 1;
    await this.buildPrompt();
    document.getElementById("aiResponse").value = "";
    this.renderQuestions([]);
    this.toast(`Step ${this.goalStep} prompt ready — click Copy!`);
  },

  async undoLast() {
    const res = await fetch("/api/undo", { method: "POST" });
    const data = await res.json();
    this.toast(data.message || data.error);
    if (res.ok) await this.loadFiles();
  },

  init() {
    const aiBox = document.getElementById("aiResponse");
    aiBox.addEventListener("paste", () => {
      if (!document.getElementById("autoProcessPaste").checked) return;
      setTimeout(() => {
        if (aiBox.value.trim()) this.runOps(true);
      }, 60);
    });

    const taskBox = document.getElementById("task");
    let smartTimer = null;
    taskBox.addEventListener("input", () => {
      if (!document.getElementById("autoSelectSmart").checked) return;
      clearTimeout(smartTimer);
      smartTimer = setTimeout(() => {
        if (this.goalStep === 1 && taskBox.value.trim().length >= 8 && this.selected.size === 0) {
          this.smartSelect();
        }
      }, 650);
    });
  },
};

App.init();
App.loadFiles();
